/* A página envia text/plain com JSON dentro — é o único Content-Type que o
   navegador trata como requisição simples, sem preflight. Dependendo da
   versão do n8n o corpo chega como string, como Buffer (rawBody) ou já
   desserializado; os três casos são tratados aqui.

   Saem dois itens: o .md legível e o .json completo com o replay. */
const entrada = $input.first().json;
let cru = entrada.body !== undefined ? entrada.body : entrada;
if (cru && cru.data && cru.type === 'Buffer') cru = Buffer.from(cru.data).toString('utf8');
if (Buffer.isBuffer(cru)) cru = cru.toString('utf8');
const dados = typeof cru === 'string' ? JSON.parse(cru) : cru;

const sessao = String(dados.sessionId || 'sem-id').replace(/[^A-Za-z0-9_-]/g, '');
const base = 'respostas/teste-preciso-de-ajuda-' + sessao;
const emBase64 = (texto) => Buffer.from(texto, 'utf8').toString('base64');

const arquivos = [
  { caminho: base + '.md', conteudo: String(dados.md || '') },
];

/* O replay só é gravado quando vem junto: o beacon de quem fecha a aba no
   meio não o carrega (teto de 64KB do navegador), e sobrescrever com vazio
   apagaria a gravação que já tinha chegado. */
if (dados.replay && dados.replay.length) {
  arquivos.push({ caminho: base + '.json', conteudo: JSON.stringify(dados) });
}

return arquivos.map((a) => ({
  json: {
    caminho: a.caminho,
    conteudoBase64: emBase64(a.conteudo),
    mensagem: 'Sessão ' + sessao,
    url: 'https://api.github.com/repos/orangebr/teste-preciso-de-ajuda/contents/' + a.caminho,
  },
}));

/* O sha do arquivo atual é obrigatório para sobrescrever. Sem ele o GitHub
   responde 422 — que é exatamente o que acontece no segundo envio da mesma
   sessão (o reenvio de um minuto, o beacon de saída, a conclusão).
   Na primeira vez o GET devolve 404 e seguimos sem sha. */
const preparados = $('Prepara os arquivos').all();

return preparados.map((item, i) => {
  const encontrado = $input.all()[i];
  const sha = encontrado && encontrado.json ? encontrado.json.sha : undefined;
  const corpo = {
    message: item.json.mensagem,
    content: item.json.conteudoBase64,
    branch: 'main',
  };
  if (sha) corpo.sha = sha;
  return { json: { url: item.json.url, corpo, caminho: item.json.caminho } };
});
